"use strict";

(() => {
  window.OFFSET_EXPAND_LESSONS({
    "first-program": {
      sections: [
        ["Follow one character all the way through", "The source file is not the program the processor executes. The compiler interprets tokens and declarations, checks types, and translates each translation unit. The linker combines generated object files with libraries. The operating system then maps the executable and prepares its entry point. That model explains why changing a header can require several files to rebuild, and why a program can compile successfully yet fail at link time.", "For a first experiment, change only the string literal. The compiler still checks the same structure, so any new behavior comes from the changed data. Then change `std::cout` to an undeclared name and observe a compile diagnostic. Finally, call a function that was declared but never defined: the source can compile, but the linker cannot supply its body. These small controlled failures teach more than memorizing error labels."],
        ["Read diagnostics as evidence", "A diagnostic gives a location and a failed assumption, not always the root cause. Start with the first error: later messages can cascade from it. Compare the named token with the surrounding declaration and check punctuation, scope, and type. For a link error, inspect the function's exact spelling, namespace, parameter types, and whether the defining source file is part of the build.", "Keep a tiny reproduction when a compiler behavior surprises you. Remove unrelated output, variables, and files until one operation remains. A minimal example makes it easier to ask a precise question, compare compiler versions, and test a fix without accidentally changing several things at once."],
        ["Extend the program without hiding its behavior", "Add a second output statement, then extract the greeting into a function. Compile after each edit. This creates a visible bridge from statements to functions and from one source file to multiple translation units. Keep output deterministic while learning: avoid adding input, current time, or randomness until you are ready to reason about those extra sources of behavior."]
      ],
      workedExample: { title: "Three diagnostics, three stages", scenario: "Suppose the goal is to print a message from a helper function defined in a separate file.", steps: ["Include the helper's header and call the declared function from main.", "Compile main.cpp and helper.cpp independently; each translation unit must know the interface it uses.", "Link both object files. If helper.cpp is absent, the compiler may be satisfied while the linker reports a missing definition."], result: "Ask which stage owns the first failed operation before changing code. A syntax error, unresolved symbol, and runtime crash need different investigations." },
      lab: { title: "Build a two-file greeting", objective: "Practice the difference between a declaration, a definition, and a link input.", prompt: "Create greeting.hpp, greeting.cpp, and main.cpp. Make the helper return a string and print that result from main.", steps: ["Declare the function in a guarded header and include that header where needed.", "Define it once in greeting.cpp; keep main.cpp focused on calling it.", "Build both source files, then deliberately omit greeting.cpp and read the link diagnostic."], completion: "A clean build prints the expected greeting, and you can explain why omitting the implementation fails after compilation.", hint: "Use the same namespace, spelling, and parameter types in the declaration, definition, and call." },
      glossary: [["Translation unit", "A source file after preprocessing, including its headers."], ["Definition", "The implementation or storage that satisfies a declaration."], ["Diagnostic", "A compiler or linker message describing a failed check."]],
      practice: ["Write down one compile error and one link error in your own words.", "Add a second function and identify which file declares and defines it."],
      checkpoints: [{ question: "Why can a source file compile while the final program fails to link?", answer: "The compiler may have seen a valid declaration, but the linker still needs a matching definition in the build inputs." }, { question: "Why is changing one thing at a time useful when learning compiler diagnostics?", answer: "It preserves a clear cause-and-effect relationship between the edit and the observed diagnostic." }]
    },
    "values-and-types": {
      sections: [
        ["Choose representations from the problem", "A type sets a range and a set of operations. If a counter cannot be negative, an unsigned type may look attractive, but signed/unsigned conversions can surprise comparisons and subtraction. Prefer a type that matches the domain and validate values at boundaries. For money, an integer number of minor units can avoid binary floating-point rounding; for measured physical quantities, the unit and precision matter as much as the storage type.", "Initialization establishes a meaningful state. `int attempts{3};` creates and initializes an object; later `attempts = 4;` assigns a new value. Braces reject many narrowing conversions, making accidental loss more visible. `const` says a name cannot be used to modify its object after initialization, which helps readers and the compiler reason about stable values."],
        ["Make conversions visible", "An input value often begins as text, not as a trusted integer. Parse it, check that parsing consumed the intended input, check its allowed range, and only then convert it to the type used by the program. A cast can change a representation, but it does not prove the original value was valid. This order is important for array sizes, account identifiers, timeouts, and allocation lengths.", "Use `auto` where it removes mechanical repetition without hiding an important contract. An iterator's exact template type is rarely useful to spell out; a public function's return type may be important documentation. The compiler still chooses one static type for `auto` at compile time."],
        ["Debug values at the boundary", "When a number looks wrong, inspect the value before and after each conversion. Check whether a literal has the type you intended, whether signedness changed, and whether arithmetic happened before the assignment. Printing a value can expose symptoms, but a range check and a test at the boundary establish the contract more directly."]
      ],
      workedExample: { title: "Validate before narrowing", scenario: "A user enters a requested number of records, and the program will store that many items.", steps: ["Read the original value into a type that can represent the accepted input domain.", "Reject negative values and values above the application limit before converting to a container size.", "Check multiplication against the maximum size before computing bytes for any manual allocation."], result: "The conversion occurs only after the program proves the value fits the destination and the operation that uses it." },
      lab: { title: "Build a checked range parser", objective: "Separate parsing, validation, and conversion.", prompt: "Accept a textual retry count from zero through five and reject empty, malformed, negative, or oversized input.", steps: ["Parse into a wider signed integer and detect trailing characters.", "Check the inclusive range before assigning to the final variable.", "Test the minimum, maximum, one value outside each bound, and malformed text."], completion: "No invalid input is silently truncated or reinterpreted as a valid count.", hint: "Keep the original string available until parsing and range checks are complete." },
      glossary: [["Initialization", "The operation that establishes an object's initial value."], ["Narrowing", "A conversion that can discard range or precision."], ["Static type", "A type determined by the compiler rather than at runtime."]],
      practice: ["Compare `int`, `std::size_t`, and `double` for three different domain values.", "Explain why a cast from a negative integer to an unsigned type does not validate the input."],
      checkpoints: [{ question: "Does `auto` make a variable dynamically typed?", answer: "No. The compiler deduces a static type from the initializer." }, { question: "Why validate before converting to an unsigned size?", answer: "A negative signed value can become a very large unsigned value, and a too-large value can be truncated by a narrower destination." }]
    },
    "decisions-and-loops": {
      sections: [
        ["State the condition in plain language", "Before writing a branch, say what each path means. `if (balance >= cost)` is a decision about affordability; `else` should describe the remaining case. Conditions that mix unrelated checks are harder to audit. Split them into named booleans or small functions when doing so reveals an important rule.", "A loop needs a starting state, a continuation condition, and measurable progress. If the condition remains true and the state does not change toward termination, the loop can run forever. If the update skips or repeats values, work is missed or duplicated. A loop invariant is a fact that stays true on each iteration; for a search, it might say every earlier element has already been checked."],
        ["Trace boundary cases deliberately", "For a count of N, the range `[0, N)` has N elements: zero is included and N is excluded. This convention makes empty ranges possible and allows adjacent ranges to meet without overlap. Test N equal to zero, one, and a typical value. If the loop accesses `items[i]`, verify the condition proves `i < items.size()` before every access.", "Avoid decrementing an unsigned value to test for a negative result. It cannot become negative; arithmetic wraps within its unsigned range. For reverse traversal, use a pattern that checks the boundary before decrementing or use reverse iterators."],
        ["Choose the loop that communicates intent", "A range-based loop is clear when each element is processed independently. An indexed loop is appropriate when the position matters. A `while` loop fits repetition controlled by input or a state transition. The syntax is a hint to the reader; it does not replace checking the loop's preconditions and termination argument."]
      ],
      workedExample: { title: "Count items without crossing the end", scenario: "Print the indexes of every element in a vector and verify that the loop runs exactly once per element.", steps: ["Initialize `i` to zero; before the first iteration, no element has been visited.", "Continue only while `i < values.size()`; this proves the current index is valid.", "Increment `i` exactly once after each body so the processed prefix grows by one."], result: "For an empty vector, the condition is false immediately. For a vector of size four, the body sees indexes zero through three." },
      lab: { title: "Trace a loop table", objective: "Make iteration count and state changes visible.", prompt: "Write a loop that sums the even values in a vector and reports how many were included.", steps: ["Create a trace table with index, current value, condition result, sum, and count.", "Run the table by hand for an empty vector and for `{2, 3, 6}`.", "Rewrite the traversal as a range-based loop and compare which version communicates the task better."], completion: "Both versions produce the same sum and count, including for an empty vector.", hint: "Keep the index only in the version where the position is useful." },
      glossary: [["Loop invariant", "A fact that remains true across each iteration."], ["Half-open range", "A range that includes its first position and excludes its end boundary."], ["Termination", "The argument that a loop eventually stops."]],
      practice: ["Change a condition from `<` to `<=` and explain which extra value it visits.", "Identify the progress step in one loop and state what happens if it is removed."],
      checkpoints: [{ question: "How many iterations does `for (i = 0; i < N; ++i)` perform for nonnegative N?", answer: "N iterations: the values are zero through N minus one." }, { question: "Why is `size()` not a valid index?", answer: "It is the one-past boundary. A container with N elements has valid indexes from zero through N minus one." }]
    },
    "functions": {
      sections: [
        ["Design around observable behavior", "A function is easier to use when its signature exposes what it needs and what it produces. A pure calculation such as `square(value)` is straightforward to test because the same input yields the same result and there are no hidden changes. A function that writes a file, changes shared state, or logs output has side effects; make those visible in its name or interface where practical.", "Declarations and definitions solve different problems. A declaration tells the compiler a call's type. The definition supplies the implementation. Keep them consistent by including the same header in the implementation file that callers use. That lets the compiler detect a mismatch instead of leaving it for a confusing link error."],
        ["Select parameter passing by meaning", "Pass small values such as integers by value. Use `const T&` for a large read-only object when avoiding a copy matters and the reference cannot outlive the argument. Use a non-const reference only when the function intentionally modifies the caller's object. If absence is a valid input state, a pointer or an explicit optional type communicates that better than a required reference.", "Prefer returning results by value. Modern C++ can efficiently return ordinary objects, and a return value keeps the relationship between operation and result visible. Avoid output parameters that make a caller inspect several unrelated variables unless the interface truly needs that form."],
        ["Keep failure in the contract", "Decide how invalid input is represented before implementing a function. A precondition may be appropriate for an internal helper; a public boundary usually needs validation and a clear error path. Do not return a value that is also a valid result to signal failure unless the ambiguity is explicitly resolved by the interface."]
      ],
      workedExample: { title: "A function with no hidden state", scenario: "Implement a function that returns the larger of two integers without changing either input.", steps: ["Choose the return type to match the result: `int`.", "Take the two inexpensive inputs by value.", "Use a comparison and return one input; test equal values as well as both orderings."], result: "The caller can test the result without setting global variables or inspecting output parameters." },
      lab: { title: "Refactor repeated logic", objective: "Turn copied behavior into an explicit, testable interface.", prompt: "Find repeated conversion or formatting logic in a small program and extract it into a named function.", steps: ["Write down the inputs, output, and any side effects before editing.", "Choose parameter types that show whether data is copied, observed, or modified.", "Call the function from at least two places and test a boundary case."], completion: "The helper has one responsibility, a clear signature, and no unexpected mutation of caller state.", hint: "If you need many output parameters, consider returning one small result struct." },
      glossary: [["Declaration", "A compiler-visible description of a name and its type."], ["Definition", "The implementation or storage for a declared entity."], ["Side effect", "A change observable beyond the function's returned value."]],
      practice: ["Rewrite a function that changes a global into one that receives the needed input.", "Explain why returning a local value is safe but returning a reference to it is not."],
      checkpoints: [{ question: "When is a read-only object commonly passed by `const T&`?", answer: "When it is relatively expensive to copy, the function only observes it, and its lifetime covers the call." }, { question: "What does a function declaration provide to a caller?", answer: "The name and type contract needed to check a call; the definition provides the implementation." }]
    },
    "references-and-pointers": {
      sections: [
        ["Separate ownership from access", "A raw pointer or reference is commonly an observer, not an owner. That distinction matters because destroying the pointer variable does not destroy the pointed-to object. Draw the lifetime relationship: who creates the object, who destroys it, and which observers may use it in between? If the owner can disappear first, a stored observer may dangle even when its address is non-null.", "References communicate that an object is required and give a name to an existing object. Pointers can express absence with `nullptr` and can be reseated. Neither automatically carries a sequence length. For ranges, use a container or `std::span` when available, or pass pointer and count together with a clear contract."],
        ["Read pointer code as a sequence of proofs", "Before dereferencing, establish that the pointer is non-null when null is possible, refers to a live object, and points to an object of the correct type. Before indexing, also establish that the index is within the valid range. A null check proves only one of these conditions; it does not repair a dangling pointer or out-of-bounds index.", "Container operations can invalidate observers. For example, vector reallocation may invalidate pointers, references, and iterators to its elements. After a mutating operation, consult the container's invalidation guarantees rather than assuming an address remained valid because the program did not crash."],
        ["Prefer value and borrow-oriented interfaces", "A function can take a required object by reference, an optional object by pointer, and an owned object by a smart-pointer or value type. These choices let readers infer the contract. Never return an address or reference to a local variable: the local's lifetime ends on return. Return a value, or return an observer only when its target lifetime is guaranteed and documented."]
      ],
      workedExample: { title: "Model a required and optional input", scenario: "A formatting function always needs a record, while a caller may optionally provide a prefix string.", steps: ["Take the record by `const Record&`; the required argument cannot be absent.", "Represent the optional prefix with an explicit optional value or a nullable pointer, and handle the absent case.", "Document that any returned string owns its characters instead of borrowing from temporary inputs."], result: "The interface separates required access, optional access, and ownership of the result." },
      lab: { title: "Audit pointer lifetimes", objective: "Find every assumption behind a dereference.", prompt: "Review a small function that receives `const int*` and a count, then safely computes a result.", steps: ["Define what the function promises when the pointer is null and when count is zero.", "Prove each index is less than count before reading it.", "Write down who owns the array and how long it must remain alive during the call."], completion: "The contract covers nullability, valid length, object lifetime, and result behavior for an empty range.", hint: "A pointer-plus-count API still relies on the caller to pass the correct count." },
      glossary: [["Observer", "A non-owning pointer or reference used to access another object's lifetime."], ["Dangling", "A pointer or reference whose target's lifetime has ended."], ["Invalidation", "An operation that makes an iterator, pointer, or reference unusable."]],
      practice: ["Find a vector operation that can invalidate a reference to an element.", "Change an optional reference parameter into a clearly nullable interface."],
      checkpoints: [{ question: "Does checking `pointer != nullptr` prove it is safe to dereference?", answer: "No. The target must also be alive, correctly typed, and within its valid range." }, { question: "What does a reference say that a pointer does not?", answer: "It normally expresses a required alias that is initialized and not reseated; it does not imply ownership." }]
    },
    "lifetime-and-raii": {
      sections: [
        ["Treat every resource as an ownership ledger", "For a resource, write down acquisition, owner, valid-use interval, and release operation. A local `std::vector` owns its allocation; a `std::lock_guard` owns a lock interval; a file wrapper can own a file handle. When the owner leaves scope, its destructor performs the matching cleanup. This works on ordinary returns and exception unwinding, avoiding branches that forget a release call.", "RAII is a lifetime design, not a synonym for smart pointers. A value object can own resources directly. A class with only standard-library members often needs no custom destructor, copy, or move operation: that is the Rule of Zero. Add custom resource logic only when an existing type cannot express the ownership policy."],
        ["Make transfer and sharing explicit", "`unique_ptr` transfers exclusive ownership when moved. `shared_ptr` keeps a resource alive while any owning copy remains, but it adds shared lifetime and reference-counting behavior. Use it only when several independent components truly need to control lifetime. A cycle of shared owners never reaches zero; a non-owning back-reference may need `weak_ptr`.", "Copying a raw operating-system handle or C pointer usually copies only its numeric value, not the underlying resource. If both copies believe they own it, cleanup can happen twice. If neither does, the resource leaks. Represent ownership in a dedicated wrapper or document and enforce a single owner."],
        ["Check exceptional paths", "Consider what happens if the second acquisition fails after the first succeeds. With separate RAII members, the first acquired resource is released automatically during unwinding. Avoid combining several manual acquisitions into one expression with unclear partial-failure behavior. Resource cleanup should be reliable even when later work returns early or throws."]
      ],
      workedExample: { title: "Watch a resource leave scope", scenario: "A function opens a file, parses one record, and may return early when that record is invalid.", steps: ["Wrap the file in a stream or RAII handle as soon as it is opened.", "Return immediately when validation fails; do not add a separate close call to every branch.", "Let the wrapper's destructor close the file when the function scope ends."], result: "Cleanup follows object lifetime, so normal completion, early return, and exceptions share one release path." },
      lab: { title: "Replace manual cleanup", objective: "Make a resource's owner visible and exception-safe.", prompt: "Take a toy function with a raw owning pointer and early returns; redesign it with `std::vector` or `std::unique_ptr`.", steps: ["List every exit path and the cleanup it currently performs.", "Choose the standard owner that matches the resource and transfer behavior.", "Add an early return and verify that cleanup remains automatic."], completion: "Each resource has one owner, no path leaks it, and no path destroys it twice.", hint: "Use shared ownership only if multiple components independently control the lifetime." },
      glossary: [["RAII", "A technique that binds resource ownership and cleanup to object lifetime."], ["Rule of Zero", "Prefer standard members so special member functions need no custom resource code."], ["Ownership transfer", "A change in which component is responsible for eventual destruction."]],
      practice: ["Draw an ownership graph for a file, parser, and result object.", "Find an early return and explain which destructors run in reverse construction order."],
      checkpoints: [{ question: "Why does RAII handle exceptions more reliably than paired manual calls?", answer: "Destructors run for constructed local objects during stack unwinding, so cleanup is tied to scope exit rather than every branch." }, { question: "When should `shared_ptr` be chosen over `unique_ptr`?", answer: "When multiple independent owners genuinely need to determine the resource's lifetime, not merely because several objects can observe it." }]
    },
    "containers-and-algorithms": {
      sections: [
        ["Choose by operations and guarantees", "A container choice should follow the operations the program performs. `vector` offers contiguous storage and fast indexed access; append is amortized constant time, while insertion in the middle shifts later elements. `map` maintains key order; `unordered_map` uses hashing and offers average-case lookup with different worst-case behavior. `array` has fixed size. Choose based on measured or clearly dominant needs, not familiarity alone.", "A container's invalidation rules are part of correctness. If `vector` grows beyond capacity, it may relocate elements and invalidate pointers, references, and iterators. Save an index or stable identifier when the algorithm needs to return to an element after mutation, or reserve capacity when the expected bound is known and appropriate."],
        ["Use algorithms as contracts", "Algorithms such as `find`, `sort`, and `accumulate` encode common operations and state iterator requirements. `sort` requires a valid ordering relation; the comparator must be consistent, including for equivalent values. A range is usually half-open, `[first, last)`, so `last` is a boundary and must not be dereferenced.", "Prefer a range-based loop for straightforward traversal and an algorithm when it clearly names the operation. Avoid forcing a complex pipeline into a single expression if it obscures intermediate state or error handling. Readability is a real requirement of maintainable code."],
        ["Estimate complexity before optimizing", "Searching a vector is linear; binary search is logarithmic but requires sorted data. An ordered map commonly provides logarithmic lookup, while an unordered map offers average constant-time lookup with hashing costs. These are broad complexity guarantees, not promises about every workload. Start with the clearest structure, measure with representative data, and change the container only when evidence supports it."]
      ],
      workedExample: { title: "Sort, then find", scenario: "A vector stores quiz scores. The program should sort them and determine whether a score of 80 appears.", steps: ["Call `std::sort` with the vector's begin and end iterators.", "Call `std::find` on the same half-open range.", "Compare the returned iterator with end before dereferencing it."], result: "The end iterator means not found; it is a boundary, never an element. Sorting changes order but does not change the number of values." },
      lab: { title: "Compare container choices", objective: "Relate data structure choice to operations and invalidation.", prompt: "Model a small inventory with repeated searches by name and occasional insertion.", steps: ["Implement a vector-based version and state its search complexity.", "Implement a map-based version and state how ordering changes iteration.", "Measure both with realistic input sizes before deciding whether the second structure is worthwhile."], completion: "The final choice is justified by required behavior, complexity, and measured workload rather than a blanket rule.", hint: "Do not compare one tiny input and conclude that all workloads behave the same." },
      glossary: [["Iterator", "An object that identifies a position in a container or range."], ["Invalidation", "Loss of the guarantees associated with an iterator or element observer."], ["Complexity", "How an operation's work grows as the input grows."]],
      practice: ["Find one operation that can invalidate a vector iterator and one that cannot.", "State the precondition for using binary search."],
      checkpoints: [{ question: "Can `end()` be dereferenced?", answer: "No. It identifies the one-past boundary of the range." }, { question: "Why must a sort comparator be consistent?", answer: "The algorithm assumes a strict weak ordering; inconsistent comparisons can violate the algorithm's preconditions." }]
    },
    "templates-and-concepts": {
      sections: [
        ["Instantiation is where requirements meet a type", "A function template is a recipe, not one runtime function that inspects arbitrary types. At a call site, template argument deduction selects types and the compiler instantiates a specialization. Expressions in the body must be valid for those types. This is why template definitions normally need to be visible where instantiation occurs, commonly in a header.", "When a diagnostic points deep inside a standard-library template, look for the first expression in your code that violates a requirement. Reduce the type or call to a small case. Concepts improve this experience by stating requirements near the interface and rejecting unsupported types with a more direct explanation."],
        ["Constrain the minimal useful interface", "A generic function should depend on only the operations its algorithm needs. If it only compares values, requiring a much broader concept can reject valid types unnecessarily. Standard concepts and ranges concepts help communicate common contracts. A concept checks compile-time expressions; it cannot guarantee that runtime data is valid or that an operation is inexpensive.", "Prefer overloads for genuinely different behavior rather than forcing every case through one increasingly complicated template. Templates improve reuse when the algorithm is the same and types vary. They are not automatically the clearest choice for a single operation."],
        ["Separate compile-time and runtime decisions", "`if constexpr` can select code based on a compile-time property; an ordinary `if` selects a path at runtime and both branches must generally be well-formed. This difference is useful when a generic implementation has type-specific operations. Keep such branches small and documented so the template remains understandable."]
      ],
      workedExample: { title: "Constrain a numeric helper", scenario: "A helper doubles an integral input. A text type should be rejected with a useful diagnostic.", steps: ["Write a function template with a type parameter.", "Use `std::integral` to state the accepted type category.", "Compile calls with an integer and a string, then read the concept-related diagnostic."], result: "The valid call instantiates the function; the invalid call is rejected during compilation rather than failing at runtime." },
      lab: { title: "Improve a template's contract", objective: "Expose generic requirements at the call boundary.", prompt: "Write a template that returns the larger of two values using a comparison operation.", steps: ["Start with the simplest implementation that uses only `<` or `>` consistently.", "Try a type that supports the operation and one that does not.", "Add an appropriate standard concept or a requires-expression and compare diagnostics."], completion: "The constraint describes the actual requirement without claiming unrelated operations are needed.", hint: "Choose a C++ standard mode that supports the concept syntax you use." },
      glossary: [["Template", "A compile-time recipe from which concrete specializations are generated."], ["Instantiation", "The process of substituting template arguments and checking the resulting specialization."], ["Concept", "A named compile-time constraint on types or expressions."]],
      practice: ["Explain why a template definition is usually placed in a header.", "Compare a runtime `if` with `if constexpr` in a type-dependent example."],
      checkpoints: [{ question: "Do concepts validate values typed by a user at runtime?", answer: "No. Concepts constrain compile-time types and expressions; runtime input still needs validation." }, { question: "Why can a template call fail even when the template declaration is accepted?", answer: "Instantiation substitutes the concrete types and checks whether the required expressions are valid." }]
    },
    "objects-and-classes": {
      sections: [
        ["Start with the invariant, not the accessor list", "An invariant is a statement that must hold for every valid object. A bounded counter might require `0 <= value <= maximum`; a file wrapper might require either a valid owned handle or an explicit empty state. The public operations are then chosen to preserve that rule. If callers can assign arbitrary public fields, the type cannot guarantee its invariant.", "Encapsulation is useful when representation decisions should remain private. It is not improved by mechanically generating a getter and setter for every field. A setter that allows an invalid value weakens the abstraction. If data members vary independently and no behavior protects them, a simple aggregate can be clearer than a class."],
        ["Design operations around state transitions", "For each public operation, write its precondition, effect, and result. What happens when a bounded counter is already full? Returning `false` can make refusal explicit; throwing may fit a different error policy. A constructor should reject or transform invalid initial state rather than creating an object that every caller must remember to repair.", "Make read-only operations `const`. That lets a caller use them on const objects and documents that they do not alter observable state. Keep implementation details private unless a real use case needs to expose them."],
        ["Test the state machine", "Test construction at the lower boundary, an ordinary update, the upper boundary, and any rejected transition. These tests describe the contract more clearly than checking that a getter returns one arbitrary value. If the type later changes its storage, callers should not need to change as long as the public contract remains the same."]
      ],
      workedExample: { title: "A counter that cannot exceed its limit", scenario: "The lesson's Counter accepts an initial value and refuses to increment after reaching its maximum.", steps: ["The constructor checks that the initial value is within the declared range.", "`increment()` checks the upper bound before mutating state and returns whether it changed the value.", "The getter is const and exposes the value without exposing writable storage."], result: "Every public path preserves `0 <= value <= maximum`; callers can test the refusal at the boundary." },
      lab: { title: "Design a Temperature value", objective: "Turn a domain rule into a type contract.", prompt: "Create a Celsius value type that cannot represent a temperature below absolute zero.", steps: ["Choose a representation and state the minimum accepted value.", "Decide how construction reports an invalid value.", "Expose a const observer and write tests for the minimum and one value below it."], completion: "Invalid states are rejected at construction, and callers cannot mutate the stored value directly.", hint: "Avoid adding setters unless they can preserve the same invariant." },
      glossary: [["Invariant", "A condition that must remain true for every valid object."], ["Encapsulation", "Keeping representation decisions behind a public contract."], ["State transition", "A change from one valid state to another through an operation."]],
      practice: ["Write a valid-state rule for a small class before adding members.", "Identify one public operation that could break the rule and design its boundary behavior."],
      checkpoints: [{ question: "When is a class more useful than a plain struct?", answer: "When its interface needs to protect an invariant or hide representation decisions; independent public data may be better as a struct." }, { question: "What should every public operation do to an invariant?", answer: "Preserve it on success and leave the object valid on any documented failure path." }]
    },
    "constructors-and-invariants": {
      sections: [
        ["Initialization order is declaration order", "C++ initializes base classes and data members in a language-defined order. Members are initialized in the order they appear in the class declaration, not the order written in the constructor's initializer list. If one member's initializer depends on another, declaration order matters. Compilers warn when the list's visual order disagrees, so fix the order rather than suppressing the warning.", "An initializer list constructs a member directly. Assigning to a member inside the constructor body means it was first default-initialized and then assigned, which may be impossible for const/reference members and can do extra work for complex types. Give scalar members in-class defaults where appropriate and initialize required state explicitly."],
        ["Make invalid construction impossible to ignore", "A constructor should establish a fully usable object. If an input violates the invariant, reject it consistently—often with an exception or a factory that returns an explicit result. Do not publish a partially initialized object and rely on a later `initialize()` call unless the type genuinely models a staged lifecycle.", "Mark single-argument constructors `explicit` unless implicit conversion is intentional. This avoids surprising conversions in unrelated expressions. Prefer brace initialization when it helps reject narrowing, but remember that braces can select initializer-list constructors; understand the overload set for the type you are constructing."],
        ["Use RAII for constructor failure", "If a constructor acquires one resource and then fails to acquire a second, already-constructed member subobjects are destroyed automatically. Store each resource in an RAII member as soon as it is acquired. Avoid raw acquisition in a constructor body followed by code that can throw before ownership is transferred to a member."]
      ],
      workedExample: { title: "Read a member initializer list", scenario: "A User stores a name string and an access level initialized from constructor parameters.", steps: ["The class declaration fixes the order: `name` first, then `access_level`.", "The initializer list constructs `name` from the supplied string and initializes the integer directly.", "If the order is reversed in the source list, the language still initializes `name` first; the mismatch is a review hazard."], result: "The class layout and constructor list should tell the same story, and the object should be valid immediately after construction." },
      lab: { title: "Add a validated constructor", objective: "Practice initializer order and constructor contracts.", prompt: "Create a `Port` type that accepts only values in the documented port-number range for your exercise.", steps: ["Declare the stored member and write the valid range next to the type.", "Initialize the member in the initializer list and validate the argument.", "Test the smallest allowed value, largest allowed value, and values just outside both boundaries."], completion: "Each constructed Port is valid, and tests demonstrate the rejection policy at the edges.", hint: "Use a named constant for the boundary instead of repeating a magic number." },
      glossary: [["Initializer list", "The constructor syntax that directly initializes bases and data members."], ["Declaration order", "The class-definition order that determines member initialization."], ["Explicit constructor", "A constructor that does not participate in unintended implicit conversions."]],
      practice: ["Reorder a class's initializer list and identify the actual construction order.", "Explain how an RAII member behaves if a later member initialization fails."],
      checkpoints: [{ question: "Does changing initializer-list order change member initialization order?", answer: "No. Data members are initialized in the order they are declared in the class." }, { question: "Why should constructors usually produce a valid object?", answer: "It keeps the invariant local to construction and prevents every caller from having to remember a repair step." }]
    },
    "enum-and-modeling": {
      sections: [
        ["Treat enumerators as states, not numbers", "`enum class` gives a finite domain a distinct type. A connection state such as `ready`, `busy`, or `failed` is not interchangeable with an unrelated integer. Scoped enumerator names avoid polluting the surrounding namespace, and implicit integer conversions are not provided. The underlying representation still exists, but the program must opt into conversions deliberately.", "Enums are useful for state machines, protocols inside one program, and configuration choices. They do not validate arbitrary input automatically. A cast from an integer can produce a value that is not one of the declared enumerators, so deserialization must range-check or map unknown values explicitly."],
        ["Make state transitions visible", "For every state, list the events that can move the object to another state and the actions allowed in that state. A switch statement makes omissions visible to compiler warnings when warnings are enabled. Adding a new enumerator should trigger a review of each switch and each display conversion.", "Avoid storing enum ordinals as a long-lived file or network format by accident. If an external format requires stable numeric values, assign and document them explicitly, version the format, and handle unknown future values."],
        ["Separate model from presentation", "A display name is not necessarily the enumerator's spelling. Write a conversion function that returns user-facing text or an error for an unknown value. This keeps logs and UI wording independent from internal identifiers and numeric representation."]
      ],
      workedExample: { title: "Handle a new state", scenario: "A connection enum gains a `closing` state after a user-visible disconnect request.", steps: ["Add the enumerator and decide which operations remain legal while closing.", "Update each state-handling switch and its tests.", "Add display text in the dedicated formatting function rather than relying on the numeric value."], result: "The state transition is explicit, and compiler warnings help reveal switches that were not updated." },
      lab: { title: "Model a download state", objective: "Use an enum to make a finite workflow reviewable.", prompt: "Model `queued`, `downloading`, `complete`, and `failed` states for a local toy program.", steps: ["List permitted transitions and reject impossible ones.", "Write a switch that handles every enumerator.", "Add a formatting function and a test for an unknown external numeric value."], completion: "The state type is scoped, transitions are documented, and invalid serialized values have a defined outcome.", hint: "Do not assume the enum's ordinal is a permanent external identifier." },
      glossary: [["Enumerator", "A named value belonging to an enumeration."], ["Scoped enum", "An `enum class` whose names are qualified and do not implicitly convert to integers."], ["State machine", "A model of states and the permitted transitions between them."]],
      practice: ["Add a state and find all switch statements that need review.", "Write down how the program handles an unknown value from a file."],
      checkpoints: [{ question: "Does `enum class` make every integer cast a valid enumerator?", answer: "No. External or cast values still need validation against the declared domain." }, { question: "Why avoid relying on enum order in a persistent file?", answer: "Reordering or inserting values can silently change the stored meaning; a stable format needs explicit representation and versioning." }]
    },
    "strings-and-text": {
      sections: [
        ["Keep bytes, code units, and characters distinct", "`std::string` owns a sequence of `char` code units. UTF-8 is a byte encoding with variable-length sequences; a visible symbol can occupy multiple bytes, and one displayed grapheme can contain multiple Unicode code points. `size()` therefore measures stored code units, not the number of characters a person sees. This distinction affects truncation, indexes, limits, and cursor positions.", "A `string_view` borrows storage; it does not extend the owner's lifetime. Returning a view into a local string or saving a view into temporary data creates a dangling view. In asynchronous code, verify that the owner remains alive until every callback or queued operation has finished."],
        ["Specify encoding at each boundary", "A file, terminal, network protocol, and Windows API may use different conventions. State which encoding a boundary expects and validate it where malformed text would cause a problem. Normalization, case folding, and grapheme segmentation are separate operations; do not apply them automatically unless the product's comparison rules require them.", "Use byte length only when the requirement is genuinely byte-based, such as a protocol field limit. A user-facing character limit needs encoding-aware logic. A substring that cuts through a UTF-8 sequence can produce invalid text even though the byte indexes were in range."],
        ["Make ownership visible in APIs", "Use `std::string` when a function needs to own text and `std::string_view` for a short-lived read-only view whose lifetime is guaranteed. If a function stores text for later, copy or move it into owned storage. Document whether the returned result owns its bytes or borrows from an argument."]
      ],
      workedExample: { title: "Measure a UTF-8 string", scenario: "A string contains `A` followed by one symbol encoded with more than one UTF-8 byte.", steps: ["Call `size()` and interpret the result as a count of stored `char` code units.", "Do not report that count as visible characters without decoding and segmenting text.", "When slicing, choose boundaries that do not split a multi-byte encoded sequence."], result: "The container provides byte-oriented storage; Unicode interpretation requires encoding-aware operations." },
      lab: { title: "Audit a text boundary", objective: "Make encoding, ownership, and length assumptions explicit.", prompt: "Design a small function that accepts a user's display name and produces a greeting.", steps: ["Choose whether the function owns a string or receives a temporary view.", "State the input encoding and the unit used for any maximum length.", "Test ASCII, a multi-byte UTF-8 symbol, empty input, and a string_view lifetime edge case."], completion: "The function's encoding, ownership, and length units are documented and the view cannot outlive its owner.", hint: "A byte count is useful for storage limits but is not automatically a character count." },
      glossary: [["Code unit", "The basic storage unit used by a text encoding or string type."], ["UTF-8", "A variable-length encoding of Unicode code points into one to four bytes."], ["string_view", "A non-owning view over character storage."]],
      practice: ["Compare `std::string::size()` with visible length for a multi-byte symbol.", "Find a function that stores its input and decide whether `string_view` is appropriate."],
      checkpoints: [{ question: "Does `string_view` keep its characters alive?", answer: "No. The backing storage must outlive every use of the view." }, { question: "What does `std::string::size()` count for UTF-8?", answer: "Stored char code units, typically bytes; it does not count grapheme clusters." }]
    },
    "file-streams": {
      sections: [
        ["Model file I/O as a sequence of fallible steps", "Opening a path can fail because it is missing, inaccessible, malformed, or interpreted relative to an unexpected working directory. Reading can fail after a successful open because the device reports an error or the input is malformed. Writing can fail when storage is full or permissions change. Check each operation at the point where its result is needed, and report the path and action without exposing sensitive file contents.", "A stream has state flags. Formatted extraction can fail because it reached end-of-file or because the next token is not representable in the requested type. `while (input >> value)` tests the read itself, so the body runs only after successful extraction. Testing `eof()` before attempting a read is backwards: end-of-file is usually discovered by the failed read."],
        ["Parse a record before applying it", "For a line-oriented format, read one full line, parse into temporary values, validate every field, then update application state. This avoids accepting half a record or partially changing state before a later field fails. Include line numbers in diagnostics and distinguish a malformed record from an I/O failure.", "A comma-separated file is not automatically full CSV. Quoting, escaped quotes, embedded delimiters, and newlines form a grammar. Use a real parser for a format with those rules instead of adding a collection of special cases to `split(',')`."],
        ["Define the serialized representation", "Do not dump a C++ object directly to a file and assume the bytes are portable. Padding, alignment, endianness, and type representation can differ. Define field widths, encoding, byte order, version, and truncation behavior, then parse fields with bounds checks."]
      ],
      workedExample: { title: "Detect a malformed token", scenario: "A text file is expected to contain integer scores, but one token contains letters.", steps: ["Attempt extraction inside the loop condition.", "Process only values whose extraction succeeded.", "After the loop, distinguish normal end-of-file from a format failure and report the relevant record."], result: "The program does not reuse a stale value or silently treat malformed input as a successful end of file." },
      lab: { title: "Build a small robust parser", objective: "Handle open failure, malformed records, and empty input distinctly.", prompt: "Read one integer per line from a file and compute the total only if every line is valid.", steps: ["Check that the file opens and include the requested path in a useful error.", "Parse each line into a temporary integer and reject trailing non-whitespace text.", "Test a missing file, empty file, valid file, malformed line, and final line without a newline."], completion: "No partial total is reported as success when a record is invalid.", hint: "Keep the parse operation separate from the step that updates the total." },
      glossary: [["Stream state", "Flags that record success, end-of-file, and failure for an I/O stream."], ["Record", "One logical input unit, such as a line or structured message."], ["Serialization", "A defined conversion between in-memory data and a persistent or transmitted format."]],
      practice: ["Write a diagnostic for an open failure and one for a malformed record.", "Explain why raw struct bytes do not form a portable file format."],
      checkpoints: [{ question: "Why put extraction in the loop condition?", answer: "It tests whether the current read succeeded before the body uses the value." }, { question: "What should happen before a parsed record changes application state?", answer: "All fields should be parsed and validated so a malformed record cannot leave a partial update." }]
    },
    "exceptions-errors": {
      sections: [
        ["Choose the error channel from the caller's decision", "Some failures are expected alternatives: a cache lookup may miss, or a user may cancel. A result type makes those choices visible in ordinary control flow. Other failures prevent a function from fulfilling its contract, such as a required file being unreadable; exceptions can propagate that failure until a layer has enough context to recover or report it. Do not use either mechanism without defining what the caller must do.", "Avoid magic values that overlap valid data. If zero is a valid result, it cannot safely mean both success with zero and failure unless a separate status channel disambiguates it. Return a small struct when a function naturally produces status and data together."],
        ["Use exception safety guarantees", "RAII cleans up resources during stack unwinding. A basic exception guarantee means invariants remain valid even if state changes; a strong guarantee means failure leaves state unchanged. For a parser, parse into temporary state and commit only after all checks pass to approach the strong guarantee. This is often simpler than trying to undo many partially applied updates.", "Catch exceptions at a boundary that can add context, retry, choose a fallback, or report a useful error. Catching in every helper obscures the original failure. An empty catch block silently discards information and often converts a visible problem into corrupted later state."],
        ["Keep failure paths testable", "List which operations can fail and what state is valid afterward. Test one normal case, one expected alternative, and one true failure. If an exception crosses an API boundary, document the expected exception behavior or translate it into the result model the caller uses."]
      ],
      workedExample: { title: "Parse, validate, then commit", scenario: "A settings file has a port number and a display name; the port is valid but the name field is malformed.", steps: ["Parse both fields into temporary variables.", "Validate the port range and the name's format before mutating the active settings.", "If either field fails, report the record and keep the original settings unchanged."], result: "This avoids publishing a half-updated configuration and gives the caller one meaningful failure to handle." },
      lab: { title: "Map failures to recovery points", objective: "Decide which layer has enough context to handle each error.", prompt: "Design error behavior for a configuration loader used by a command-line tool.", steps: ["List missing-file, malformed-value, and optional-setting cases.", "Classify each as an expected result or a failure that interrupts the operation.", "Choose where to add file and line context, and write tests for the chosen behavior."], completion: "Every failure is observable, contextual, and leaves the program in a valid state.", hint: "Do not catch an exception merely to print a generic message and continue with invalid settings." },
      glossary: [["Error channel", "The interface mechanism used to communicate success and failure."], ["Strong guarantee", "An operation either succeeds or leaves the prior state unchanged."], ["Stack unwinding", "The process of destroying local objects while an exception propagates."]],
      practice: ["For a lookup function, decide whether not-found is an error or an ordinary result.", "Identify an exception boundary where the program can add useful context."],
      checkpoints: [{ question: "Where should an exception usually be caught?", answer: "At the layer that can recover, add meaningful context, choose a fallback, or report the failure." }, { question: "How can parsing avoid a partially updated object?", answer: "Parse and validate temporary state first, then commit the complete result only after all checks pass." }]
    },
    "move-semantics": {
      sections: [
        ["Understand the expression before using std::move", "C++ distinguishes lvalues, which identify persistent objects, from rvalues and xvalues, which can be treated as expiring values for overload resolution. `std::move` is a cast that produces an xvalue; it does not copy bytes, transfer a resource, or destroy the source by itself. A move constructor or assignment operator must be selected for any transfer to occur.", "For a simple integer, moving is effectively the same as copying. For a string or vector, a move can transfer ownership of an allocation, but the exact operation and complexity belong to the type's contract. Return local values directly and let copy elision and move rules do their work; adding `std::move` to every return can block useful optimization."],
        ["Use a moved-from object only under its guarantee", "A moved-from standard-library object remains valid, but its value is generally unspecified unless the type documents more. It may be destroyed or assigned a new value. Do not depend on the old contents. For a user-defined type, design move operations so the source remains safely destructible and both objects maintain their invariants.", "A `const` object usually cannot bind to a typical move operation that needs a non-const rvalue, so `std::move` on const data may still copy. Measure performance before adding special members: a custom move implementation increases the invariants you must maintain."],
        ["Prefer Rule of Zero", "Standard containers and smart pointers already implement resource-aware moves. A type composed of those members often needs no custom move constructor or assignment operator. Write custom operations only when the class directly owns a resource whose default behavior is incorrect, and then test self-assignment, moved-from state, and destruction."]
      ],
      workedExample: { title: "Read the move expression", scenario: "A string is passed into a destination string with `std::move(source)`.", steps: ["The name `source` is an lvalue expression even though its type is `std::string`.", "`std::move(source)` casts that expression to an xvalue.", "The destination's constructor overload set can now select a move constructor; afterward, source is valid but not guaranteed to keep its previous text."], result: "The cast enables a move; the selected operation performs it. Reassign source before relying on a new value." },
      lab: { title: "Trace overload selection", objective: "See the distinction between an lvalue, an xvalue, a copy, and a move.", prompt: "Create a small type that logs copy and move construction, then pass it into functions by value and by const reference.", steps: ["Call with a named object and note which overload is selected.", "Call with `std::move(object)` and note which overload becomes viable.", "Remove unnecessary moves from local returns and compare the result."], completion: "You can explain which overload ran without claiming that `std::move` itself moved data.", hint: "Keep a separate test for a simple integer to show that move syntax is not inherently faster." },
      glossary: [["Value category", "An expression property that affects which overloads can bind to it."], ["xvalue", "An expiring-value expression that can enable resource reuse."], ["Move operation", "A constructor or assignment that may transfer a resource from another object."]],
      practice: ["Find an unnecessary `std::move` in a local return and explain why it can be removed.", "State which operations are safe on a moved-from string."],
      checkpoints: [{ question: "Does `std::move(x)` itself perform a resource transfer?", answer: "No. It casts the expression so a move operation may be selected." }, { question: "What guarantee should you assume for a moved-from standard-library object?", answer: "It remains valid, but its value is generally unspecified unless the type documents otherwise." }]
    },
    "smart-pointers": {
      sections: [
        ["Select an owner from the lifetime graph", "Start by drawing which object creates a resource and which objects need it to remain alive. If there is one owner, `unique_ptr` or a direct value usually expresses the policy. If several independent owners determine when destruction occurs, `shared_ptr` may be appropriate. If another object only needs to observe a shared owner, `weak_ptr` can avoid extending lifetime or forming a cycle.", "A raw pointer returned by `get()` is an observer; it does not increase the reference count. It is safe only while an owning smart pointer remains alive and does not reset the resource. A raw pointer or reference is often the clearest function parameter for borrowing when the caller guarantees lifetime."],
        ["Avoid accidental shared ownership", "Copying a `shared_ptr` changes lifetime: the target remains alive until the last owning copy is destroyed. That may be exactly what a cache or asynchronous task needs, but it can make ownership hard to reason about when used everywhere. A cycle of shared owners keeps every reference count above zero. Make non-owning graph edges weak, or redesign the ownership tree.", "Smart pointers do not make the pointee thread-safe. The control block supports shared ownership bookkeeping, but concurrent reads and writes to the object still need a synchronization rule."],
        ["Prefer values when dynamic lifetime is unnecessary", "A local `std::string`, `std::vector`, or small value type does not need heap allocation merely because a pointer is familiar. Values simplify ownership and reduce indirection. Use a smart pointer when identity, polymorphism, or a dynamic lifetime genuinely matters, not as a wrapper around every object."]
      ],
      workedExample: { title: "One owner, several observers", scenario: "A document editor owns a document while several views read and display it.", steps: ["Let the application or document manager own the document with one clear owner.", "Pass references or raw observer pointers to synchronous view operations when the owner outlives the call.", "If views can outlive the manager, model that lifecycle explicitly rather than silently converting every relationship to shared ownership."], result: "The ownership graph is easy to inspect, and observing the document does not accidentally prolong its lifetime." },
      lab: { title: "Draw and implement ownership", objective: "Match pointer types to ownership rather than convenience.", prompt: "Model a report owned by one manager and displayed by two short-lived views.", steps: ["Draw the owner and observer edges before writing code.", "Implement the report as a value or unique owner and have views borrow it.", "Add one scenario where a view outlives the manager and decide how the design should handle it."], completion: "Every lifetime transition is explicit; no raw pointer is mistaken for an owner and no shared cycle is introduced.", hint: "If observers may outlive an owner, use a deliberate lifetime protocol or a weak observer that can detect expiration." },
      glossary: [["unique_ptr", "A movable smart pointer representing exclusive ownership."], ["shared_ptr", "A smart pointer that shares a reference-counted lifetime."], ["weak_ptr", "A non-owning observer of an object managed by shared_ptr."]],
      practice: ["Replace an unnecessary shared_ptr with a value or unique_ptr.", "Find a raw pointer returned by `get()` and state how its lifetime is guaranteed."],
      checkpoints: [{ question: "Which pointer type is the normal default for one dynamic owner?", answer: "`std::unique_ptr`, because it expresses exclusive ownership and explicit transfer." }, { question: "Does shared_ptr make the object safe for concurrent mutation?", answer: "No. It manages shared lifetime, not synchronization of the pointed-to object." }]
    },
    "lambdas-callables": {
      sections: [
        ["The capture list is stored state", "A lambda creates a closure object. Capturing by value stores a copy of a local value; capturing by reference stores an alias to the original object. An init-capture can move an object into the closure. This is an ownership and lifetime decision, not just shorthand syntax. A `[&]` capture can hide dependencies because later edits may silently add another referenced local.", "A callback used immediately by `std::find_if` normally runs before the surrounding scope ends. A callback placed in a queue, stored in a member, or invoked on another thread may run much later. Review where the closure is created, how long it is stored, and every possible invocation path."],
        ["Capturing this does not own the object", "A lambda that captures `this` stores a pointer to the current object; it does not keep that object alive. If the callback can run after destruction, it may access a dangling pointer. Use a clear cancellation/join lifecycle or capture an appropriate ownership handle when delayed execution is required.", "Constness also matters. A lambda's call operator is const by default for value captures; `mutable` permits changing the closure's stored copy, not the original local. A reference capture can change the original object, subject to the referenced type and lifetime."],
        ["Make callback behavior testable", "Keep the callable's required data explicit and minimize captured state. A named function object can be clearer when the operation has multiple stages or persistent state. Test both the callback result and the lifetime contract, especially when an executor or event system stores it beyond the current call."]
      ],
      workedExample: { title: "Filter with a value capture", scenario: "Find the first score at or above a threshold using `std::find_if`.", steps: ["Store the threshold in a local `const int`.", "Capture that threshold by value in the predicate.", "Compare each element and check the returned iterator against end before reading it."], result: "The predicate owns a stable copy of its threshold and runs synchronously during the algorithm call." },
      lab: { title: "Audit deferred callbacks", objective: "Recognize captures that can outlive their referents.", prompt: "Write a function that creates a callback for later execution and decide what the callback owns.", steps: ["Start with a local string used by the callback and capture it by reference.", "Explain why invoking the callback after return is unsafe.", "Change the capture to own a copy or move, then compare the lifetime and cost."], completion: "The saved callback does not depend on a destroyed local or an unowned `this` pointer.", hint: "For asynchronous work, include cancellation and object shutdown in the lifetime design." },
      glossary: [["Closure", "The callable object produced by a lambda expression."], ["Capture", "State copied, moved, or referenced from the enclosing scope."], ["Deferred callback", "A callable stored for invocation after its creation point."]],
      practice: ["Replace a broad capture with explicit captures and list what the callable owns.", "Trace the lifetime of a captured object through queueing and cancellation."],
      checkpoints: [{ question: "Why can a reference capture fail in a saved callback?", answer: "The referenced local may be destroyed before the callback is invoked." }, { question: "Does capturing `this` extend the object's lifetime?", answer: "No. It copies the pointer; a separate lifetime guarantee is required." }]
    },
    "testing-assertions": {
      sections: [
        ["Test contracts, not implementation details", "A test should state an input and an observable expectation. Tests are strongest when they exercise public behavior rather than private helper layout, because internal organization can change without changing the contract. Include ordinary input, empty input, boundaries, invalid input, and regression cases for bugs that have occurred.", "Keep tests deterministic. Avoid relying on current time, network availability, random ordering, or mutable global state unless the test controls those dependencies. When external systems are involved, inject a small interface or use a local fixture so the test can repeat the same path."],
        ["Assertions and input validation have different jobs", "`assert` is useful for internal assumptions during development, but release builds can disable it. Never use it as the only validation of a file, network request, command-line argument, or user value. External input needs an ordinary error path that exists in production.", "Sanitizers instrument executed paths to catch selected classes of memory and undefined-behavior errors. AddressSanitizer and UndefinedBehaviorSanitizer are useful development tools, but they only find what their instrumentation covers on the paths you run. A clean run is evidence, not proof."],
        ["Make a failure actionable", "When a test or sanitizer fails, preserve the input and first useful diagnostic. Reduce the case until one operation remains, then fix the earliest invalid assumption. Do not suppress a warning because a test passes once. Add a regression test that fails before the fix and succeeds after it."]
      ],
      workedExample: { title: "Test a range boundary", scenario: "A function returns an element at an index or reports that the index is invalid.", steps: ["Test index zero for a non-empty collection.", "Test the last valid index, `size() - 1`.", "Test `size()` itself and an empty collection without subtracting from zero."], result: "The tests describe both valid access and the boundary condition that must be rejected." },
      lab: { title: "Build a small regression suite", objective: "Cover behavior, boundaries, and a failure path.", prompt: "Write tests for a function that accepts a vector and returns the average or an explicit failure for an empty vector.", steps: ["Test a one-element vector and a multi-element vector.", "Test empty input and choose a failure representation that cannot be confused with a valid average.", "Introduce a regression in a local copy and confirm the test catches it."], completion: "Tests cover valid values and the empty case without using assert as external-input validation.", hint: "A result type or optional return can distinguish no result from a numeric zero." },
      glossary: [["Regression test", "A test that ensures a previously fixed behavior stays fixed."], ["Sanitizer", "A build-time/runtime tool that instruments selected error classes."], ["Test oracle", "The expected behavior against which a test compares its result."]],
      practice: ["Add a test for the first invalid index after the valid range.", "Run the same deterministic test repeatedly and identify hidden sources of nondeterminism."],
      checkpoints: [{ question: "Does a passing sanitizer run prove a program is memory-safe for all inputs?", answer: "No. It shows no instrumented error was found on the executed paths in that run." }, { question: "Why is assert not a production check for untrusted input?", answer: "It may be disabled in release builds and does not provide the program's normal failure handling." }]
    },
    "build-linking": {
      sections: [
        ["Follow a symbol through each stage", "A source file is preprocessed into a translation unit, then compiled into an object file. The object file contains machine code and symbol references. The linker combines object files and libraries, resolves external names, and produces an executable or library. At startup, the loader maps the image and dependencies. A declaration error, unresolved symbol, and missing runtime DLL belong to different stages.", "Headers publish interfaces to translation units. Ordinary non-inline function definitions should generally have one owner source file. Include the header from that source file as well as its callers so a signature mismatch is caught during compilation. Include guards prevent repeated inclusion within one translation unit; they do not prevent duplicate definitions from separate source files."],
        ["Make the build graph reproducible", "List every source file, generated file, include path, library, and compiler option that a target needs. A clean build is important because stale object files can hide missing dependencies. Build systems such as CMake describe targets and dependencies so incremental rebuilds happen for the right reasons.", "If a link fails, read the exact missing symbol, including namespaces and parameter types. If a duplicate symbol appears, locate every definition. Do not solve either problem by including a `.cpp` file; that collapses build boundaries and often creates new duplicates."],
        ["Separate interface, implementation, and configuration", "A header should be self-contained and should not rely on another header having been included first. Keep platform and compiler assumptions explicit. Record language standard, warning level, and external dependencies so another machine can reproduce the build. A successful local build is not enough if the project depends on an undeclared file or environment variable."]
      ],
      workedExample: { title: "Diagnose a missing implementation", scenario: "`main.cpp` includes `math.hpp` and calls `add`, but the build omits `math.cpp`.", steps: ["The compiler sees the declaration and accepts the call in main.cpp.", "The compiler also builds math.cpp separately when it is included in the target.", "The linker reports an unresolved reference if the object file containing the definition is missing."], result: "Add the implementation source to the target rather than copying its body into every caller." },
      lab: { title: "Create a clean multi-file target", objective: "Practice declarations, definitions, and a reproducible build.", prompt: "Split an existing single-file program into a header, implementation file, and main file.", steps: ["Move a function declaration into a self-contained header with an include guard.", "Move the single definition into its own source file and include the header there.", "Configure a clean build, then remove one source file to observe the link failure."], completion: "A clean build succeeds from an empty build directory and each function has one declaration contract and one definition.", hint: "Compile the implementation and caller independently before linking them together." },
      glossary: [["Object file", "A compiled translation unit containing code and symbol information."], ["Linker", "A tool that combines object files and resolves symbols."], ["Build graph", "The targets and dependencies that define how outputs are produced."]],
      practice: ["Explain the difference between a missing declaration and a missing definition.", "Delete a build directory and rebuild from scratch to expose undeclared dependencies."],
      checkpoints: [{ question: "What does an include guard protect against?", answer: "Repeated inclusion of a header within one translation unit, not duplicate definitions across separate source files." }, { question: "Why should the implementation source include its public header?", answer: "It makes the compiler check that the definition still matches the interface callers see." }]
    }
  });
})();
